1	import java.util.List;
2	import java.util.Random;
3	import java.util.Iterator;
4	import java.util.ArrayList;
5	
6	/**
7	 * A class representing shared characteristics of animals.
8	 *
9	 * @version 2022.03.01
10	 */
11	public abstract class Animal extends Organism
12	{
13	    // The level of food an animal has consumed, increases when it eats
14	    private int foodLevel;
15	    // Indicates whether an animal can give birth or not
16	    private boolean female;
17	    // Indicates whether the animal is nocturnal or not
18	    private boolean nocturnal;
19	    // The animal's age
20	    private double age;
21	    // Indicates whether the animal is sleeping or not
22	    private boolean sleeping;
23	    
24	    /**
25	     * Create a new animal at location in field.
26	     * 
27	     * @param randomAge If true, the animal will have a random age
28	     * @param field The field currently occupied.
29	     * @param location The location within the field.
30	     */
31	    public Animal(boolean randomAge, Field field, Location location)
32	    {
33	        super(randomAge, field, location);
34	        nocturnal = false;
35	        Random rand = new Random();
36	        female = rand.nextBoolean();
37	        setWaterLevel(rand.nextInt(10) + 5);
38	        sleeping = false;
39	        if(!randomAge) {
40	            setAge(0);
41	            foodLevel = rand.nextInt(10) + 8;
42	        }
43	    }
44	    
45	    /**
46	     * Make this animal act - that is: make it do
47	     * whatever it wants/needs to do.
48	     * @param newAnimals A list to receive newly born animals.
49	     */
50	    public void act(List<Actor> newOrganisms) {
51	        // All animals eat; all organisms also increment age and water level
52	        super.act(newOrganisms);
53	        incrementHunger();
54	        if(isAlive() && !sleeping) {        
55	            // Move towards a source of food if found
56	            giveBirth(newOrganisms);  
57	            Location newLocation = null;
58	            if(getWaterLevel() < 3) {
59	                newLocation = findWater();
60	            }
61	            if (newLocation == null && getFoodLevel() < 8) {
62	                newLocation = findFood(getPrey());
63	            }
64	            if (newLocation == null) {
65	                newLocation = findMate();
66	            }
67	            if(newLocation == null) { 
68	                // No food found - try to move to a free location.
69	                newLocation = getField().freeAdjacentLocation(getLocation());
70	            }
71	            
72	            // See if it was possible to move.
73	            if(newLocation != null) {
74	                setLocation(newLocation);
75	            }
76	            else {
77	                // Overcrowding.
78	                setDead();
79	            }
80	        }
81	        else if (sleeping) {
82	            // code for what to do when sleeping
83	            sleeping = false;
84	        }
85	    }
86	    
87	    /**
88	     * Move towards another animal of the same species to find a mate to breed with
89	     * 
90	     * @return The location of a potential mate if found, null if not
91	     */
92	    public Location findMate() 
93	    {
94	        Field field = getField();
95	        List<Location> adjacent = field.adjacentLocations(getLocation());
96	        Iterator<Location> it = adjacent.iterator();
97	        while(it.hasNext()) {
98	            Location where = it.next();
99	            // Checks nearby location (adjacent to adjacent locations)
100	            List<Location> adjacent2 = field.adjacentLocations(where);
101	            Iterator<Location> it2 = adjacent2.iterator();
102	            while (it2.hasNext()) {
103	                Location where2 = it2.next();
104	                Object animal = field.getObjectAt(where);
105	                if(animal != null && animal.getClass().equals(this.getClass())) {
106	                    return where2;
107	                }
108	            }
109	        }
110	        return null;
111	    }
112	    
113	    /**
114	     * Look for prey adjacent to the current location.
115	     * Only the first live prey is eaten.
116	     * @return Where food was found, or null if it wasn't.
117	     */
118	    protected Location findFood(ArrayList<String> preyList)
119	    {
120	        Field field = getField();
121	        List<Location> adjacent = field.adjacentLocations(getLocation());
122	        Iterator<Location> it = adjacent.iterator();
123	        while(it.hasNext()) {
124	            Location where = it.next();
125	            Object food = field.getObjectAt(where);
126	            if(food!= null) {
127	                if(preyList.contains(food.getClass().getName())) {
128	                    Organism prey = (Organism) food;
129	                    if(prey.isAlive()) { 
130	                        prey.setDead();
131	                        int increment = prey.getFoodValue() + this.getFoodLevel();
132	                        this.setFoodLevel(increment);
133	                        int newWaterLevel = getWaterLevel() + 5;
134	                        this.setWaterLevel(newWaterLevel);
135	                        return where;  
136	                    }
137	                }
138	            }
139	        }
140	        return null;
141	    }
142	    
143	    /**
144	     * Look for water adjacent to the animal's current location
145	     * @return Where water was found, or null if it wasn't 
146	     */
147	    protected Location findWater() {
148	        super.findWater();
149	        return null;
150	    }
151	    
152	    /**
153	     * Make the animal more hungry. This could result in the animal's death.
154	     */
155	    public void incrementHunger()
156	    {
157	        foodLevel--;
158	        if(foodLevel <= 0) {
159	            setDead();
160	        }
161	    }
162	    
163	    /**
164	     * Check whether or not this animal is to give birth at this step.
165	     * New births will be made into free adjacent locations.
166	     * @param newAnimals A list to return newly born animals.
167	     * @return A list of the free adjacent locations for new young to be born into
168	     */
169	    protected List<Location> giveBirth(List<Actor> newAnimals)
170	    {
171	        // New animals are born into adjacent locations.
172	        // Get a list of adjacent free locations.
173	        Field field = getField();
174	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
175	        List<Location> adjacent = field.adjacentLocations(getLocation());
176	        Iterator<Location> it = adjacent.iterator();
177	        while(it.hasNext()) {
178	            Location where = it.next();
179	            Object animal = field.getObjectAt(where);
180	            // can only breed if next to an animal of opposite sex
181	            if(animal != null && this.getClass().equals(animal.getClass())) {
182	                Animal mate = (Animal) animal;
183	                if (isFemale() != mate.isFemale()) {
184	                    return free;
185	                }
186	                else {
187	                    return null;
188	                }
189	            }
190	        }    
191	        return null;
192	    }
193	    
194	    /**
195	     * @param foodValue The level of food an animal has eaten
196	     */
197	    protected void setFoodLevel(int foodValue)
198	    {
199	        foodLevel = foodValue;
200	    }
201	    
202	    /** 
203	     * @return The level of food an animal has eaten
204	     */
205	    protected int getFoodLevel()
206	    {
207	        return foodLevel;
208	    }
209	    
210	    /** 
211	     * @return True if this animal is a female, capable of breeding
212	     */
213	    public boolean isFemale()
214	    {
215	        return female;
216	    }
217	    
218	    /** 
219	     * @return True if this animal is a female, capable of breeding
220	     */
221	    public void setNocturnal()
222	    {
223	        nocturnal = true;
224	    }
225	    
226	    /** 
227	     * @return True if this animal is nocturnal, false if not
228	     */
229	    public boolean isNocturnal()
230	    {
231	        return nocturnal;
232	    }
233	    
234	    /**
235	     * Sets the sleeping boolean variable to the opposite state it currently has.
236	     */
237	    public void setSleepStatus(){
238	        sleeping = ! sleeping;
239	    }
240	    
241	    /**
242	     * @return Returns list of prey for each animal
243	     */
244	    abstract public ArrayList<String> getPrey();
245	}
