1	import java.util.Random;
2	import java.util.List;
3	import java.util.Iterator;
4	import java.util.ArrayList;
5	
6	/**
7	 * A class to represent all living creatures in the simulation
8	 * Shared characteristics between organisms include whether they are alive,
9	 * their location on the field and their age
10	 *
11	 * @version 2022.02.27
12	 */
13	public abstract class Organism implements Actor
14	{
15	    // Whether the organism is alive or not
16	    private boolean alive;
17	    // The organism's field
18	    private Field field;
19	    // The organism's position in the field
20	    private Location location;
21	    // The water level of the organism
22	    private int waterLevel;
23	    // Whether the organism is infected with a disease or not.
24	    private boolean infected;
25	    // The organism's age
26	    private int age;
27	    
28	    /** 
29	     * Constructor for organisms - places new organism in location
30	     * 
31	     * @param randomAge If true, the organism will have random age
32	     * @param field The field currently occupied.
33	     * @param location The location within the field.
34	     */
35	    public Organism(boolean randomAge, Field field, Location location) 
36	    {
37	        alive = true;
38	        this.field = field;
39	        setLocation(location);
40	        age = 0;
41	    }
42	    
43	     /**
44	     * Make this organism act - that is: make it do
45	     * whatever it wants/needs to do.
46	     * All organisms will age and lose water with each step that they act
47	     *
48	     * @param newOrganisms A list to receive newly born organisms
49	     */
50	    public void act(List<Actor> newOrganisms)
51	    {
52	        incrementAge();
53	        decreaseWaterLevel();
54	    }
55	    
56	    /**
57	     * Return the organism's location.
58	     * @return The organism's location.
59	     */
60	    protected Location getLocation()
61	    {
62	        return location;
63	    }
64	    
65	     /**
66	     * Place the organism at the new location in the given field.
67	     * @param newLocation The organism's new location.
68	     */
69	    protected void setLocation(Location newLocation)
70	    {
71	        if(location != null) {
72	            field.clear(location);
73	        }
74	        location = newLocation;
75	        field.place(this, newLocation);
76	    }
77	    
78	    /**
79	     * Return the organism's field.
80	     * @return The organism's field.
81	     */
82	    protected Field getField()
83	    {
84	        return field;
85	    }
86	    
87	    /**
88	     * Check whether the organism is alive or not.
89	     * @return true if the organism is still alive.
90	     */
91	    protected boolean isAlive()
92	    {
93	        return alive;
94	    }
95	
96	    /**
97	     * Indicate that the organism is no longer alive.
98	     * It is removed from the field.
99	     */
100	    public void setDead()
101	    {
102	        alive = false;
103	        if(location != null) {
104	            field.clear(location);
105	            location = null;
106	            field = null;
107	        }
108	    }
109	    
110	    /**
111	     * Increase the age.
112	     */
113	    public void incrementAge()
114	    {
115	        age = age + 1;
116	    }
117	    
118	    /**
119	     * @return The value that eating this organism gives predator
120	     */
121	    abstract public int getFoodValue();
122	    
123	    /**
124	     * Look for water adjacent to the organism's current location
125	     * @return Where water was found, or null if it wasn't 
126	     */
127	    protected Location findWater() {
128	        Field field = getField();
129	        List<Location> adjacent = field.adjacentLocations(getLocation());
130	        Iterator<Location> it = adjacent.iterator();
131	        while(it.hasNext()){
132	            Location where = it.next();
133	            Object waterSource = field.getObjectAt(where);
134	            if(waterSource instanceof Lake) {
135	                Lake lake = (Lake) waterSource;
136	                // if there is enough water left to drink
137	                if(lake.getVolume() >= lake.getWaterValue()){
138	                    // increase drinking organism's water level and reduces lake's water level
139	                    int newWaterLevel = getWaterLevel() + lake.getWaterValue();
140	                    this.setWaterLevel(newWaterLevel);
141	                    lake.reduceVolume(lake.getWaterValue());
142	                    return where;
143	                }
144	                // if only a little bit of water left to drink, drinks remnants 
145	                // then empties lake
146	                else if (lake.getVolume() >= 0) {
147	                    int newWaterLevel = getWaterLevel() + lake.getVolume();
148	                    this.setWaterLevel(newWaterLevel);
149	                    lake.setVolume(0);
150	                    lake.setDead();
151	                    return where;
152	                }
153	                else if(lake.getVolume() <=0){
154	                    lake.setDead();
155	                    return null;
156	                }
157	            }
158	        }
159	        return null;
160	    }
161	    
162	    /** 
163	     * Lower's the organism's water level - may result in its death
164	     */
165	    public void decreaseWaterLevel(){
166	        int newWaterLevel = getWaterLevel() - 1;
167	        setWaterLevel(newWaterLevel);
168	        if(getWaterLevel() <=0) {
169	            setDead();
170	        }
171	    }
172	    
173	    /**
174	     * @param waterValue The level of water an organism has 
175	     */
176	    protected void setWaterLevel(int newWaterLevel)
177	    {
178	        waterLevel = newWaterLevel;
179	    }
180	    
181	    /**
182	     * @return The current level of water an organism has
183	     */
184	    protected int getWaterLevel()
185	    {
186	        return waterLevel;
187	    }
188	    
189	    /**
190	     * @param age The current age of the organism
191	     */
192	    protected void setAge(int age)
193	    {
194	        this.age = age;
195	    }
196	    
197	    /**
198	     * @return Current age of the organism
199	     */
200	    protected double getAge()
201	    { 
202	        return age;
203	    }
204	    
205	    /**
206	     * Infects the organism with a disease
207	     */
208	    protected void setInfected() {
209	        infected = true;
210	    }
211	    
212	    /** 
213	     * Infection does not last forever in water, removes disease
214	     */
215	    protected void notInfected() {
216	        infected = false;
217	    }
218	    
219	    /**
220	     * @return Whether the organism is infected with a disease
221	     */
222	    protected boolean isInfected(){
223	        return infected;
224	    }
225	}
