1	import java.util.List;
2	import java.util.Iterator;
3	import java.util.Random;
4	import java.util.ArrayList;
5	import java.util.Arrays;
6	
7	/**
8	 * A simple model of a lion.
9	 * Lions age, move, find food (gazelles), find water, find mates, breed and die.
10	 *
11	 * @version 2022.02.27
12	 */
13	public class Lion extends Animal
14	{
15	    // Characteristics shared by all lions (class variables).
16	    
17	    // The age at which a lion can start to breed.
18	    private static final int BREEDING_AGE = 15;
19	    // The age to which a lion can live.
20	    private static final int MAX_AGE = 200;
21	    // The likelihood of a lion breeding.
22	    private static final double BREEDING_PROBABILITY = 0.5;
23	    // The maximum number of births a lion can give.
24	    private static final int MAX_LITTER_SIZE = 4;
25	    // The probability of the animal successfully hunting their food
26	    private final double SUCCESSFUL_HUNT_PROB = 0.65;
27	    // // The food value of a lion - not eaten by any predators so initial
28	    // food value of newly generated lions
29	    private static final int LION_FOOD_VALUE = 15;
30	    // A shared random number generator to control breeding.
31	    private static final Random rand = Randomizer.getRandom(); 
32	    // A list of the prey that the lion eats
33	    private static final ArrayList<String> prey = new ArrayList(Arrays.asList("Gazelle"));
34	
35	    /**
36	     * Create a lion. A lion can be created as a new born (age zero
37	     * and not hungry) or with a random age and food level.
38	     * 
39	     * @param randomAge If true, the lion will have random age and hunger level.
40	     * @param field The field currently occupied.
41	     * @param location The location within the field.
42	     */
43	    public Lion(boolean randomAge, Field field, Location location)
44	    {
45	        super(randomAge, field, location);
46	        if(randomAge) {
47	            this.setAge(rand.nextInt(MAX_AGE));
48	            this.setFoodLevel(LION_FOOD_VALUE + 5);
49	        }
50	    }
51	
52	    /**
53	     * This is what the lion does most of the time: it hunts for
54	     * gazelles. In the process, it might breed, die of hunger,
55	     * or die of old age.
56	     * @param field The field currently occupied.
57	     * @param newLions A list to return newly born lions.
58	     */
59	    public void act(List<Actor> newLions)
60	    {
61	        super.act(newLions);
62	    }
63	
64	    /**
65	     * Increase the age. This could result in the lion's death.
66	     */
67	    public void incrementAge() {
68	        super.incrementAge();    
69	        if(this.getAge() > MAX_AGE) {
70	            setDead();
71	        }
72	    }
73	
74	    /**
75	     * Look for gazelles adjacent to the current location.
76	     * Only the first live gazelle is eaten.
77	     * @return Where food was found, or null if it wasn't.
78	     */
79	    private Location findFood()
80	    {
81	        if (rand.nextDouble() < SUCCESSFUL_HUNT_PROB) {
82	            super.findFood(prey);
83	        }
84	        return null;
85	    }
86	
87	    /**
88	     * Check whether or not this lion is to give birth at this step.
89	     * New births will be made into free adjacent locations.
90	     * @param newLionss A list to return newly born lions.
91	     */
92	    protected List<Location> giveBirth(List<Actor> newLions)
93	    {
94	        Field field = getField();
95	        int births = breed();
96	        List<Location> free = super.giveBirth(newLions);
97	        if (free != null) {
98	            for(int b = 0; b < births && free.size() > 0; b++) {
99	                Location loc = free.remove(0);
100	                Lion young = new Lion(false, field, loc);
101	                if (this.isInfected()) {
102	                    young.setInfected();
103	                }
104	                newLions.add(young);
105	            }
106	        }
107	        return null;
108	    }
109	
110	    /**
111	     * Generate a number representing the number of births,
112	     * if it can breed.
113	     * @return The number of births (may be zero).
114	     */
115	    private int breed()
116	    {
117	        int births = 0;
118	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
119	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
120	        }
121	        return births;
122	    }
123	
124	    /**
125	     * A lion can breed if it is female and has reached the breeding age.
126	     */
127	    private boolean canBreed()
128	    {
129	        return (this.isFemale() && this.getAge() >= BREEDING_AGE);
130	    }
131	    
132	     /**
133	     * @return The food value of a lion
134	     */
135	    public int getFoodValue()
136	    { 
137	        return LION_FOOD_VALUE;
138	    }
139	
140	    /**
141	     * @return The probability of a lion successfully hunting its prey
142	     */
143	    public double getHuntProb(){
144	        return SUCCESSFUL_HUNT_PROB;
145	    }
146	    
147	    /**
148	     * @return The list of prey which it eats 
149	     */
150	    public ArrayList<String> getPrey()
151	    {
152	        return prey;
153	    }
154	}

1	import java.util.List;
2	import java.util.Iterator;
3	import java.util.Random;
4	import java.util.ArrayList;
5	import java.util.Arrays;
6	
7	/**
8	 * A simple model of a hyena.
9	 * Hyenas age, move, eat gazelles, and die.
10	 *
11	 * @version 2016.02.29 (2)
12	 */
13	public class Hyena extends Animal
14	{
15	    // Characteristics shared by all hyenas (class variables).
16	    
17	    // The age at which a hyena can start to breed.
18	    private static final int BREEDING_AGE = 10;
19	    // The age to which a hyena can live.
20	    private static final int MAX_AGE = 150;
21	    // The likelihood of a hyena breeding.
22	    private static final double BREEDING_PROBABILITY = 0.60;
23	    // The maximum number of births.
24	    private static final int MAX_LITTER_SIZE = 2;
25	    // The probability of the animal successfully hunting their food
26	    private final double SUCCESSFUL_HUNT_PROB = 0.63;
27	    // The food value of a hyena - not eaten by any predators so initial
28	    // food value of newly generated hyenas
29	    private static final int HYENA_FOOD_VALUE = 15;
30	    // A shared random number generator to control breeding.
31	    private static final Random rand = Randomizer.getRandom();
32	    // A list of the prey that the hyena eats
33	    private static final ArrayList<String> prey = new ArrayList(Arrays.asList("Fennec Fox", "Gazelle"));
34	
35	    /**
36	     * Create a hyena. A hyena can be created as a new born (age zero
37	     * and not hungry) or with a random age and food level.
38	     * 
39	     * @param randomAge If true, the hyena will have random age and hunger level.
40	     * @param field The field currently occupied.
41	     * @param location The location within the field.
42	     */
43	    public Hyena(boolean randomAge, Field field, Location location)
44	    {
45	        super(randomAge, field, location);
46	        setNocturnal();
47	        if(randomAge) {
48	            this.setAge(rand.nextInt(MAX_AGE));
49	            this.setFoodLevel(HYENA_FOOD_VALUE);
50	        }
51	    }
52	
53	    /**
54	     * This is what the hyena does most of the time: it hunts for
55	     * gazelles. In the process, it might breed, die of hunger,
56	     * or die of old age.
57	     * @param field The field currently occupied.
58	     * @param newHyenas A list to return newly born hyenas.
59	     */
60	    public void act(List<Actor> newHyenas)
61	    {
62	        super.act(newHyenas);
63	    }
64	
65	    /**
66	     * Increase the age. This could result in the hyena's death.
67	     */
68	    public void incrementAge() {
69	        super.incrementAge();    
70	        if(this.getAge() > MAX_AGE) {
71	            setDead();
72	        }
73	    }
74	
75	    /**
76	     * Look for prey adjacent to the current location.
77	     * Only the first live prey is eaten.
78	     * @return Where food was found, or null if it wasn't.
79	     */
80	    private Location findFood()
81	    {
82	        if (rand.nextDouble() < SUCCESSFUL_HUNT_PROB) {
83	            super.findFood(prey);
84	        }
85	        return null;
86	    }
87	
88	    /**
89	     * Check whether or not this hyena is to give birth at this step.
90	     * New births will be made into free adjacent locations.
91	     * @param newhyenas A list to return newly born hyenas.
92	     */
93	    protected List<Location> giveBirth(List<Actor> newHyenas)
94	    {
95	         Field field = getField();
96	        int births = breed();
97	        List<Location> free = super.giveBirth(newHyenas);
98	        if (free != null) {
99	            for(int b = 0; b < births && free.size() > 0; b++) {
100	                Location loc = free.remove(0);
101	                Hyena young = new Hyena(false, field, loc);
102	                if (this.isInfected()) {
103	                    young.setInfected();
104	                }
105	                newHyenas.add(young);
106	            }
107	        } 
108	        return null;
109	    }
110	
111	    /**
112	     * Generate a number representing the number of births,
113	     * if it can breed.
114	     * @return The number of births (may be zero).
115	     */
116	    private int breed()
117	    {
118	        int births = 0;
119	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
120	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
121	        }
122	        return births;
123	    }
